#!/bin/bash

# Fails only on schema-generator warnings that a change introduces. Most configs already
# carry generator drift on the base branch, so each config's warnings are compared with
# the same config on origin/$GITHUB_BASE_REF, generated by the base branch's own generator.

base_ref="${GITHUB_BASE_REF:-main}"
base_root=$(mktemp -d)
trap 'rm -rf "$base_root"' EXIT
git archive "origin/${base_ref}" scripts src/configurations | tar -x -C "$base_root"
exit_code=0

# Prints one line per warning: Python spreads each UserWarning over several lines, and the
# file:line prefix is dropped so edits to the generator don't make every warning look new.
warnings_in() {
    local output
    # A generator that fails to run prints no warnings; fail instead of passing silently.
    if ! output=$(cd "$1" && python scripts/schemaGenerator.py -name="$2" "$3" 2>&1); then
        echo "$output" >&2
        return 1
    fi
    echo "$output" | awk '
        /UserWarning: / { if (w != "") print w; sub(/^.*UserWarning: /, ""); w = $0; next }
        /warnings\.warn\(/ { if (w != "") print w; w = ""; next }
        w != "" { w = w " " $0 }
        END { if (w != "") print w }
    ' | sed -E 's/[[:space:]]+/ /g; s/^ //; s/ $//' | sort
}

for directory in $(printf '%s\n' "$@" | grep -oE '^src/configurations/(destinations|sources)/[^/]+/' | sort -u); do
    directory=${directory%/}
    name=$(basename "$directory")
    selector=$(basename "$(dirname "$directory")")
    selector=${selector%s}

    warnings=$(warnings_in . "$name" "$selector") || exit 1
    [ -z "$warnings" ] && continue

    # A config that is new in this change has no base copy, so all of its warnings count as new.
    base_warnings=$(warnings_in "$base_root" "$name" "$selector") || exit 1
    new_warnings=$(comm -23 <(echo "$warnings") <(echo "$base_warnings"))

    if [ -n "$new_warnings" ]; then
        echo "New warnings found for name: ${name} selector: ${selector}:"
        echo "$new_warnings"
        # Positional diffs change text when existing drift shifts, so show what base already had.
        echo "Warnings already on origin/${base_ref}:"
        echo "${base_warnings:-(none)}"
        exit_code=1
    else
        echo "For name: ${name} selector: ${selector}: all warnings already exist on origin/${base_ref}."
    fi
done
exit $exit_code
